
-- ─── TOOLS ────────────────────────────────────────────────────────────────────
INSERT INTO resources (slug, resource_type, title, description, long_description, category, compatible_platforms, is_free, is_featured, source_url, author, tags)
VALUES
-- SwarmClaw tools
('swarmclaw-web-search', 'tool', 'SwarmClaw Web Search', 'Real-time web search tool for AI agents — queries the live web and returns structured results with citations.', 'SwarmClaw''s web search tool enables agents to query the live internet, retrieve ranked results, and extract content. Supports multi-query batching and citation formatting compatible with Claude, ChatGPT, and Open WebUI.', 'web-search', ARRAY['SwarmClaw','Claude','ChatGPT','Open WebUI'], true, true, 'https://www.swarmclaw.ai/', 'SwarmClaw', ARRAY['search','web','real-time','citations']),
('swarmclaw-code-executor', 'tool', 'SwarmClaw Code Executor', 'Sandboxed Python/JS code execution tool — runs agent-generated code safely in an isolated environment.', 'Executes Python and JavaScript code in a secure sandbox. Supports file I/O, package imports, and returns stdout/stderr. Integrates directly with SwarmClaw agent workflows and Open WebUI tool calls.', 'code-execution', ARRAY['SwarmClaw','Open WebUI'], true, true, 'https://www.swarmclaw.ai/', 'SwarmClaw', ARRAY['code','python','javascript','sandbox','execution']),
('swarmclaw-memory-store', 'tool', 'SwarmClaw Memory Store', 'Persistent vector memory tool for agents — stores and retrieves contextual information across sessions.', 'Provides agents with long-term memory via vector embeddings. Supports semantic search over stored facts, conversation history, and user preferences. Works across SwarmClaw, Open WebUI, and compatible chat platforms.', 'memory', ARRAY['SwarmClaw','Open WebUI','LobeHub'], true, false, 'https://www.swarmclaw.ai/', 'SwarmClaw', ARRAY['memory','vector','embeddings','persistence','context']),
('swarmclaw-file-reader', 'tool', 'SwarmClaw File Reader', 'Multi-format file reading tool — parses PDF, DOCX, CSV, JSON, and TXT files for agent consumption.', 'Reads and extracts structured content from common file formats. Agents can reference uploaded documents, spreadsheets, and reports. Output is normalized Markdown for seamless injection into agent context.', 'file-processing', ARRAY['SwarmClaw','Open WebUI'], true, false, 'https://www.swarmclaw.ai/', 'SwarmClaw', ARRAY['files','pdf','docx','csv','parsing']),
('swarmclaw-image-analysis', 'tool', 'SwarmClaw Image Analysis', 'Vision tool for AI agents — analyzes images, extracts text (OCR), and describes visual content.', 'Provides multimodal vision capability to agents. Accepts image URLs or base64, returns natural language descriptions, extracted text, object lists, and scene analysis. Compatible with Claude Vision and GPT-4o.', 'vision', ARRAY['SwarmClaw','Claude','ChatGPT'], true, false, 'https://www.swarmclaw.ai/', 'SwarmClaw', ARRAY['vision','ocr','images','multimodal']),

-- OpenClaw tools
('openclaw-api-connector', 'tool', 'OpenClaw API Connector', 'Universal REST API connector — lets agents call any HTTP endpoint with custom headers, auth, and body templates.', 'A flexible tool for connecting agents to any REST API. Supports OAuth2, API key, and basic auth. Define endpoint templates, map response fields, and chain API calls across agent turns. Used by OpenClaw for platform integrations.', 'api-integration', ARRAY['Claude','ChatGPT','Open WebUI'], true, true, 'https://openclaw.ai/', 'OpenClaw', ARRAY['api','rest','http','integration','connector']),
('openclaw-data-transformer', 'tool', 'OpenClaw Data Transformer', 'Data transformation tool — converts between JSON, CSV, XML, and YAML formats within agent workflows.', 'Enables agents to transform data between formats on the fly. Supports JSONPath queries, field mapping, schema validation, and bulk record processing. Essential for ETL-style agent pipelines.', 'data-processing', ARRAY['Claude','ChatGPT'], true, false, 'https://openclaw.ai/', 'OpenClaw', ARRAY['data','transform','json','csv','etl']),
('openclaw-webhook-trigger', 'tool', 'OpenClaw Webhook Trigger', 'Webhook trigger tool — agents can send outbound HTTP events to any endpoint when conditions are met.', 'Allows agents to fire outbound webhooks on task completion, error states, or custom triggers. Configurable payload templates, retry logic, and delivery confirmation. Integrates with Zapier, Make, and n8n workflows.', 'automation', ARRAY['Claude','ChatGPT','Open WebUI'], true, false, 'https://openclaw.ai/', 'OpenClaw', ARRAY['webhook','automation','trigger','integration']),

-- SwarmDock tools
('swarmdock-docker-runner', 'tool', 'SwarmDock Docker Runner', 'Container execution tool — agents can build and run Docker containers for isolated task execution.', 'Enables AI agents to spin up Docker containers on demand for isolated code execution, data processing, and service deployment. Supports custom images, volume mounts, and environment variables. Core tool in SwarmDock''s infrastructure layer.', 'infrastructure', ARRAY['SwarmClaw','Open WebUI'], true, true, 'https://www.swarmdock.ai/', 'SwarmDock', ARRAY['docker','containers','infrastructure','devops']),
('swarmdock-kubernetes-deploy', 'tool', 'SwarmDock Kubernetes Deploy', 'K8s deployment tool — agents can deploy, scale, and manage Kubernetes workloads programmatically.', 'Provides agents with full Kubernetes lifecycle management: create deployments, services, and ingress rules; scale replicas; roll back deployments; monitor pod health. Built for DevOps agents automating infrastructure tasks.', 'infrastructure', ARRAY['SwarmClaw'], true, false, 'https://www.swarmdock.ai/', 'SwarmDock', ARRAY['kubernetes','k8s','devops','deployment','infrastructure']),
('swarmdock-log-analyzer', 'tool', 'SwarmDock Log Analyzer', 'Log analysis tool — agents parse container and system logs to diagnose errors and performance issues.', 'Ingests logs from Docker, Kubernetes, and system sources. Agents can query log streams, detect anomalies, extract error patterns, and generate incident summaries. Integrates with Loki, Elasticsearch, and raw log files.', 'monitoring', ARRAY['SwarmClaw','Open WebUI'], true, false, 'https://www.swarmdock.ai/', 'SwarmDock', ARRAY['logs','monitoring','debugging','kubernetes','docker']),

-- MultiOn tools
('multion-browser-control', 'tool', 'MultiOn Browser Control', 'Full browser automation tool — AI agents browse the web, fill forms, click buttons, and extract data autonomously.', 'MultiOn''s flagship browser control tool gives agents the ability to navigate any website, interact with UI elements, log into services, fill out forms, and extract structured data. Used for web automation, scraping, and RPA workflows.', 'browser-automation', ARRAY['Claude','ChatGPT','Open WebUI'], false, true, 'https://docs.multion.ai/welcome', 'MultiOn', ARRAY['browser','automation','web','rpa','scraping']),
('multion-session-manager', 'tool', 'MultiOn Session Manager', 'Browser session persistence tool — maintains authenticated browser state across multiple agent turns.', 'Manages persistent browser sessions so agents can log in once and maintain authentication across multiple tasks. Supports session snapshots, cookie management, and parallel session pools for concurrent agent workflows.', 'browser-automation', ARRAY['Claude','ChatGPT'], false, false, 'https://docs.multion.ai/welcome', 'MultiOn', ARRAY['browser','sessions','auth','persistence']),
('multion-vision-extractor', 'tool', 'MultiOn Vision Extractor', 'Web content extraction tool — uses vision to extract structured data from any webpage regardless of DOM structure.', 'Combines visual browser rendering with LLM vision to extract structured data from any page layout. Works on dynamic SPAs, tables, dashboards, and complex UI patterns that CSS selectors can''t handle.', 'browser-automation', ARRAY['Claude','ChatGPT'], false, false, 'https://docs.multion.ai/welcome', 'MultiOn', ARRAY['vision','extraction','web','structured-data']),

-- Open WebUI tools
('openwebui-rag-tool', 'tool', 'Open WebUI RAG Tool', 'Retrieval-Augmented Generation tool — lets agents query uploaded documents and knowledge bases in real time.', 'Open WebUI''s built-in RAG tool indexes uploaded PDFs, DOCs, and text files into a vector store. Agents can query the knowledge base semantically and inject retrieved context into responses. Supports multiple embedding models.', 'knowledge-base', ARRAY['Open WebUI'], true, true, 'https://openwebui.com/', 'Open WebUI', ARRAY['rag','retrieval','documents','knowledge-base','embeddings']),
('openwebui-image-gen-tool', 'tool', 'Open WebUI Image Generation Tool', 'Image generation tool for Open WebUI — generates images via DALL-E, Stable Diffusion, or ComfyUI from agent prompts.', 'Connects Open WebUI to local or remote image generation backends. Supports DALL-E 3, Stable Diffusion (AUTOMATIC1111), and ComfyUI workflows. Agents can generate images mid-conversation and display them inline.', 'image-generation', ARRAY['Open WebUI'], true, false, 'https://openwebui.com/', 'Open WebUI', ARRAY['image-generation','dall-e','stable-diffusion','comfyui']),
('openwebui-speech-tool', 'tool', 'Open WebUI Speech Tool', 'Text-to-speech and speech-to-text tool — adds voice input/output to Open WebUI agent conversations.', 'Integrates TTS (OpenAI, ElevenLabs, local Kokoro) and STT (Whisper) into agent sessions. Users can speak to their agents and receive voice responses. Configurable per model and per conversation.', 'voice', ARRAY['Open WebUI'], true, false, 'https://openwebui.com/', 'Open WebUI', ARRAY['tts','stt','voice','whisper','elevenlabs']),

-- Hermes Agent tools (from PDF)
('hermes-skills-system', 'tool', 'Hermes Skills System', 'Procedural memory system for Hermes Agent — create reusable skills the agent builds and improves over time.', 'Hermes Agent''s Skills System provides procedural memory: the agent autonomously creates, refines, and reuses skills across sessions. Skills are stored as structured prompts, compatible with agentskills.io standard, shareable via the Skills Hub, and community-contributed. This enables Hermes to continuously improve its task execution capabilities.', 'agent-memory', ARRAY['Open WebUI','Claude'], true, true, 'https://hermes-agent.nousresearch.com/docs', 'Nous Research', ARRAY['skills','memory','procedural','hermes','nous-research']),
('hermes-mcp-integration', 'tool', 'Hermes MCP Integration', 'MCP server connector for Hermes Agent — connect any MCP server, filter tools, and safely extend Hermes capabilities.', 'Hermes Agent''s MCP integration supports connecting to any Model Context Protocol server. Features tool filtering to limit agent access, safe extension patterns, and practical setup tutorials. Works with filesystem, GitHub, Brave Search, Puppeteer, and all standard MCP servers.', 'mcp-integration', ARRAY['Open WebUI'], true, true, 'https://hermes-agent.nousresearch.com/docs', 'Nous Research', ARRAY['mcp','hermes','tools','integration','nous-research']),
('hermes-messaging-gateway', 'tool', 'Hermes Messaging Gateway', '20+ platform messaging tool — deploy Hermes Agent to Telegram, Discord, Slack, WhatsApp, Signal, and more.', 'The Hermes Messaging Gateway connects the agent to 20+ chat platforms from a single configuration. Supports Telegram, Discord, Slack, WhatsApp, Signal, Matrix, Mattermost, Email, SMS, DingTalk, Feishu, WeCom, Weixin, QQ Bot, Yuanbao, Home Assistant, Microsoft Teams, Google Chat, and more. One agent, every surface.', 'messaging', ARRAY['Open WebUI'], true, true, 'https://hermes-agent.nousresearch.com/docs', 'Nous Research', ARRAY['telegram','discord','slack','whatsapp','messaging','hermes']),
('hermes-cron-scheduler', 'tool', 'Hermes Cron Scheduler', 'Built-in cron scheduling for Hermes Agent — automate tasks on any schedule with delivery to any platform.', 'Hermes Agent includes a native cron scheduler allowing you to define recurring tasks with full crontab syntax. Outputs are delivered to any configured platform (Telegram, Discord, email, etc.). Supports complex multi-step scheduled workflows and trajectory export for RL training.', 'automation', ARRAY['Open WebUI'], true, false, 'https://hermes-agent.nousresearch.com/docs', 'Nous Research', ARRAY['cron','scheduling','automation','hermes','nous-research']),
('hermes-voice-mode', 'tool', 'Hermes Voice Mode', 'Real-time voice interaction for Hermes Agent — full voice I/O in CLI, Telegram, Discord, and Discord VC.', 'Hermes Agent Voice Mode enables real-time spoken interaction across CLI and messaging platforms. Supports push-to-talk, continuous listening, and Discord Voice Channel integration. Works with local Whisper STT and multiple TTS backends.', 'voice', ARRAY['Open WebUI'], true, false, 'https://hermes-agent.nousresearch.com/docs', 'Nous Research', ARRAY['voice','tts','stt','discord','hermes']),

-- SkillsLLM tools
('skillsllm-prompt-optimizer', 'tool', 'SkillsLLM Prompt Optimizer', 'Prompt optimization tool — analyzes and rewrites prompts to maximize performance across different LLM backends.', 'SkillsLLM''s prompt optimizer tool evaluates prompt structure, clarity, and instruction specificity. Provides rewrite suggestions optimized for different model families (Claude, GPT, Llama, Mistral). Tracks performance metrics across model variants.', 'prompt-engineering', ARRAY['Claude','ChatGPT','Open WebUI','LobeHub'], true, false, 'https://skillsllm.com/', 'SkillsLLM', ARRAY['prompts','optimization','llm','engineering']),
('skillsllm-skill-validator', 'tool', 'SkillsLLM Skill Validator', 'Skill validation and testing tool — evaluate agent skills against benchmark tasks and score quality.', 'Validates AI agent skills by running them against curated benchmark tasks. Produces quality scores, identifies failure modes, and suggests improvements. Part of the agentskills.io ecosystem for community-contributed skills.', 'testing', ARRAY['Open WebUI','Claude'], true, false, 'https://skillsllm.com/skill/swarmclaw', 'SkillsLLM', ARRAY['testing','validation','benchmarks','skills','quality']),

-- Omni agent skills tools
('omni-query-tool', 'tool', 'Omni Query Tool', 'Omni platform query tool — agents access Omni''s semantic data layer to query business metrics and dashboards.', 'Enables AI agents to query the Omni business intelligence platform using natural language. The tool translates agent questions into Omni''s semantic model queries, retrieves metrics, and returns formatted data for analysis and reporting.', 'analytics', ARRAY['Claude','ChatGPT'], false, false, 'https://docs.omni.co/developers/agent-skills', 'Omni', ARRAY['analytics','bi','dashboards','data','omni']),
('omni-dashboard-embed', 'tool', 'Omni Dashboard Embed Tool', 'Dashboard embedding tool — programmatically embed Omni dashboard tiles and charts into agent responses.', 'Allows agents to retrieve and embed specific Omni dashboard visualizations into responses. Supports parameterized dashboard tiles, live data refresh, and chart export to PNG/SVG for sharing in reports.', 'analytics', ARRAY['Claude','ChatGPT'], false, false, 'https://docs.omni.co/developers/agent-skills', 'Omni', ARRAY['dashboards','embed','analytics','charts','omni']),

-- Agency Agents tools
('agency-agents-orchestrator', 'tool', 'Agency Agents Orchestrator', 'Multi-agent orchestration tool — coordinate multiple specialized agents to complete complex multi-step tasks.', 'From the Agency Agents framework, this orchestration tool manages agent hierarchies, task delegation, inter-agent communication, and result aggregation. Supports parallel agent execution and dependency-based task graphs.', 'orchestration', ARRAY['Claude','ChatGPT','Open WebUI'], true, true, 'https://agencyagents.dev/agents', 'Agency Agents', ARRAY['orchestration','multi-agent','delegation','coordination']),
('agency-agents-task-planner', 'tool', 'Agency Agents Task Planner', 'Hierarchical task planning tool — breaks complex goals into executable sub-tasks with dependency tracking.', 'Decomposes high-level goals into structured task trees. Each sub-task is assigned to a specialized agent or tool. Tracks completion status, handles failures with retry logic, and reports progress back to the orchestrating agent.', 'orchestration', ARRAY['Claude','ChatGPT'], true, false, 'https://agencyagents.dev/agents', 'Agency Agents', ARRAY['planning','tasks','decomposition','orchestration'])

ON CONFLICT (slug) DO NOTHING;
